import type { CSSProperties } from "react";

import type { AudioVisualizerProps } from "@/components/control-ui/audio-visualizer";
import { audioVisualizerHistory } from "@/components/control-ui/lib/audio-visualizer-levels";
import { cn } from "@/components/control-ui/lib/cn";

const LINE_VIEWBOX_WIDTH = 100;
const LINE_VIEWBOX_HEIGHT = 32;
const LINE_CENTER = LINE_VIEWBOX_HEIGHT / 2;
const LINE_PADDING = 3;
const MIN_AMPLITUDE = 0;
const CURVE_TENSION = 0.18;

type Point = { x: number; y: number };
type AudioVisualizerPathStyle = CSSProperties & { d: string };

function smoothPath(points: readonly Point[]) {
  const [first, ...rest] = points;
  if (!first) return "";

  return rest.reduce(
    (path, point, index) => {
      const previous = points[index] ?? first;
      const controlOffset = (point.x - previous.x) * CURVE_TENSION;
      return `${path} C ${(previous.x + controlOffset).toFixed(2)} ${previous.y.toFixed(2)}, ${(point.x - controlOffset).toFixed(2)} ${point.y.toFixed(2)}, ${point.x.toFixed(2)} ${point.y.toFixed(2)}`;
    },
    `M ${first.x.toFixed(2)} ${first.y.toFixed(2)}`,
  );
}

function envelopePath(levels: readonly number[]) {
  const envelope = levels.length === 1 ? [levels[0] ?? 0, levels[0] ?? 0] : levels;
  const step = LINE_VIEWBOX_WIDTH / Math.max(1, envelope.length - 1);
  const maxAmplitude = LINE_CENTER - LINE_PADDING;
  const upper = envelope.map((level, index) => ({
    x: index * step,
    y: LINE_CENTER - MIN_AMPLITUDE - Math.sqrt(level) * (maxAmplitude - MIN_AMPLITUDE),
  }));
  const lower = envelope.map((level, index) => ({
    x: index * step,
    y: LINE_CENTER + MIN_AMPLITUDE + Math.sqrt(level) * (maxAmplitude - MIN_AMPLITUDE),
  }));
  const lowerReversed = [...lower].reverse();

  return `${smoothPath(upper)} L ${lowerReversed[0]?.x.toFixed(2) ?? 0} ${lowerReversed[0]?.y.toFixed(2) ?? LINE_CENTER}${smoothPath(lowerReversed).replace(/^M [^C]+/, "")} Z`;
}

export function AudioVisualizer({ levels, points, active = true, className, style, ...props }: AudioVisualizerProps) {
  const visible = audioVisualizerHistory(levels, points, active).map(({ level }) => level);
  const path = envelopePath(visible);
  const pathStyle: AudioVisualizerPathStyle = { d: `path('${path}')` };
  const labelled = Boolean(props["aria-label"] || props["aria-labelledby"]);

  return (
    <div
      data-control-ui="audio-visualizer"
      data-control-family="audio-visualizer"
      data-slot="root"
      data-variant="line"
      data-active={active ? "true" : undefined}
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : true}
      className={cn("shrink-0 overflow-hidden", className)}
      style={style}
      {...props}
    >
      <svg
        data-control-ui="audio-visualizer"
        data-control-family="audio-visualizer"
        data-slot="track"
        data-active={active ? "true" : undefined}
        viewBox={`0 0 ${LINE_VIEWBOX_WIDTH} ${LINE_VIEWBOX_HEIGHT}`}
        preserveAspectRatio="none"
        aria-hidden="true"
        className="size-full overflow-visible"
      >
        <path
          data-control-ui="audio-visualizer"
          data-control-family="audio-visualizer"
          data-slot="baseline"
          d={`M 0 ${LINE_CENTER} H ${LINE_VIEWBOX_WIDTH}`}
          vectorEffect="non-scaling-stroke"
        />
        <path
          data-control-ui="audio-visualizer-line"
          data-control-family="audio-visualizer"
          data-slot="waveform"
          d={path}
          style={pathStyle}
          strokeWidth="1"
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>
    </div>
  );
}

@layer components {
  :where([data-control-family="audio-visualizer"][data-variant]) {
    --cui-audio-visualizer-radius: var(--radius-control);
    --cui-audio-visualizer-bar-background: oklch(from var(--primary) l c h / 0.8);
    --cui-audio-visualizer-bar-radius: var(--radius-control);
    --cui-audio-visualizer-bar-size: calc(var(--spacing) * 1);
    --cui-audio-visualizer-bar-gap: 1px;
    --cui-audio-visualizer-line-fill: oklch(from var(--primary) l c h / 0.18);
    --cui-audio-visualizer-line-stroke: oklch(from var(--primary) l c h / 0.8);
    --cui-audio-visualizer-baseline-stroke: oklch(from var(--border) l c h / 0.55);
    --_audio-visualizer-inline-sign: 1;
  }
  :where([data-control-family="audio-visualizer"][data-variant]:dir(rtl)) {
    --_audio-visualizer-inline-sign: -1;
  }
  :where([data-control-family="audio-visualizer"][data-slot="root"][data-variant]) {
    block-size: calc(var(--spacing) * 7);
    inline-size: calc(var(--spacing) * 44);
    padding-inline: calc(var(--spacing) * 1.5);
    --_audio-visualizer-bar-track-filter: none;
    border-radius: var(--cui-audio-visualizer-radius);
  }

  :where([data-control-family="audio-visualizer"][data-slot="root"][data-variant="bars"]) {
    padding-block: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="audio-visualizer"][data-slot="track"]) {
    gap: var(--cui-audio-visualizer-bar-gap);
    opacity: 0.55;
    transition: opacity var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-slot="track"][data-active="true"]) {
    opacity: 1;
  }

  :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
    inline-size: var(--cui-audio-visualizer-bar-size);
    min-inline-size: 0;
    flex-shrink: 1;
    transition:
      opacity var(--duration-base) var(--ease-emphasized),
      filter var(--duration-base) var(--ease-emphasized),
      translate var(--duration-base) var(--ease-emphasized);
    filter: var(--_audio-visualizer-bar-track-filter);
  }

  @starting-style {
    :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
      opacity: 0;
      --_audio-visualizer-bar-track-filter: blur(var(--blur-xs));
      filter: var(--_audio-visualizer-bar-track-filter);
      translate: calc(var(--spacing) * var(--_audio-visualizer-inline-sign)) 0;
    }
  }

  :where([data-control-family="audio-visualizer"][data-slot="bar"]) {
    background: var(--cui-audio-visualizer-bar-background);
    border-radius: var(--cui-audio-visualizer-bar-radius);
    opacity: var(--_audio-visualizer-level-opacity);
    transition:
      clip-path var(--duration-base) var(--ease-standard),
      opacity var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-slot="baseline"]) {
    stroke: var(--cui-audio-visualizer-baseline-stroke);
  }

  :where([data-control-family="audio-visualizer"][data-slot="waveform"]) {
    fill: var(--cui-audio-visualizer-line-fill);
    stroke: var(--cui-audio-visualizer-line-stroke);
    transition: d var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-variant="bars"][data-active="true"] [data-slot="bar"]) {
    transition: none;
  }

  :where([data-control-family="audio-visualizer"][data-variant="line"]:not([data-active="true"]) [data-slot="waveform"]) {
    opacity: 0;
  }

  :where([data-control-family="audio-visualizer"][data-variant="line"]:not([data-active="true"]) [data-slot="baseline"]) {
    stroke-dasharray: 1 4;
    stroke-linecap: round;
  }

  :where([data-control-family="audio-visualizer"][data-slot="root"][data-variant="bar"]) {
    --cui-audio-visualizer-bar-size: calc(var(--spacing) * 1.5);
    --cui-audio-visualizer-bar-gap: calc(var(--spacing) * 0.75);
    padding-block: calc(var(--spacing) * 1);
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"] [data-slot="track"]) {
    display: flex;
    block-size: 100%;
    align-items: center;
    justify-content: center;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="start"] [data-slot="track"]) {
    align-items: flex-start;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="end"] [data-slot="track"]) {
    align-items: flex-end;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"] [data-slot="bar"]) {
    min-inline-size: 0;
    max-inline-size: var(--cui-audio-visualizer-bar-size);
    flex: 1;
    transform-origin: center;
    transition:
      height var(--duration-fast) var(--ease-standard),
      opacity var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="start"] [data-slot="bar"]) {
    transform-origin: top;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-align="end"] [data-slot="bar"]) {
    transform-origin: bottom;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-idle="pulse"]:not([data-active="true"]) [data-slot="bar"]) {
    animation: cui-audio-bar-pulse calc(var(--duration-slow) * 4) var(--ease-standard) infinite;
  }

  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-idle="wave"]:not([data-active="true"]) [data-slot="bar"]),
  :where([data-control-family="audio-visualizer"][data-variant="bar"][data-loading="true"] [data-slot="bar"]) {
    animation: cui-audio-bar-pulse calc(var(--duration-slow) * 4) var(--ease-standard) infinite;
    animation-delay: var(--_audio-visualizer-delay);
  }

  @keyframes cui-audio-bar-pulse {
    0%,
    100% {
      transform: scaleY(1);
    }
    50% {
      transform: scaleY(4);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    :where([data-control-family="audio-visualizer"] [data-slot]) {
      animation: none;
      transition: none;
    }
  }
}

@property --cui-audio-visualizer-bar-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-audio-visualizer-bar-gap {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-audio-visualizer-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-audio-visualizer-bar-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

